 import unittest
from candidate import digitSum

class TestDigitSum(unittest.TestCase):
    def test_empty_string(self):
        self.assertEqual(digitSum(""), 0)

    def test_lowercase_characters(self):
        self.assertEqual(digitSum("abab"), 0)

    def test_mixed_case_characters(self):
        self.assertEqual(digitSum("abAB"), 131)

    def test_multiple_uppercase_characters(self):
        self.assertEqual(digitSum("abcCd"), 67)

    def test_string_with_only_uppercase_characters(self):
        self.assertEqual(digitSum("HELLOE"), 69)

    def test_string_with_multiple_repeated_uppercase_characters(self):
        self.assertEqual(digitSum("woArBld"), 131)

    def test_string_with_non_ascii_characters(self):
        with self.assertRaises(ValueError):
            digitSum("äöü")

    def test_string_with_leading_trailing_whitespace(self):
        self.assertEqual(digitSum("   abcCd   "), 67)

    def test_string_with_none_value(self):
        self.assertEqual(digitSum(None), None)

    def test_string_with_integer_value(self):
        with self.assertRaises(TypeError):
            digitSum(123)

if __name__ == '__main__':
    unittest.main()
